text:
.usage {
  --usage-bg: var(--card);
  --usage-card: var(--card);
  --usage-line: color-mix(in srgb, var(--accent) 16%, var(--card));
  --usage-line-hover: color-mix(in srgb, var(--accent) 38%, var(--card));
  --usage-text: var(--foreground);
  --usage-muted: var(--muted-foreground);
  --usage-accent: var(--link);
  --usage-inset: color-mix(in srgb, var(--accent) 3%, var(--card));
  --usage-green: var(--color-usage-usage-green-1);
  --usage-yellow: var(--status-warning-text);
  --usage-queued-color: var(--color-usage-usage-queued-color-2);
  --usage-gradient: linear-gradient(
    135deg,
    var(--color-usage-usage-gradient-3),
    var(--color-usage-usage-gradient-4)
  );
  --usage-plan-gradient: linear-gradient(
    135deg,
    var(--color-usage-usage-plan-gradient-5),
    var(--color-usage-usage-plan-gradient-6)
  );
  --usage-glow: 0 8px 40px var(--color-usage-usage-glow-7);
  --usage-button-ink: var(--color-usage-usage-button-ink-8);
  --usage-ring-start: var(--color-usage-usage-ring-start-9);
  --usage-ring-end: var(--color-usage-usage-ring-end-10);
}
:global([data-theme="dark"]) .usage {
  --usage-gradient: linear-gradient(
    135deg,
    var(--color-usage-usage-gradient-11),
    var(--color-usage-usage-gradient-12)
  );
  --usage-plan-gradient: var(--usage-gradient);
  --usage-glow: 0 0 60px var(--color-usage-usage-glow-13);
  --usage-button-ink: var(--color-usage-usage-button-ink-14);
  --usage-ring-start: var(--color-usage-usage-gradient-11);
  --usage-ring-end: var(--color-usage-usage-gradient-12);
  --usage-bg: var(--color-usage-usage-bg-15);
  --usage-card: var(--color-usage-usage-card-16);
  --usage-line: var(--color-usage-usage-line-17);
  --usage-line-hover: var(--color-usage-usage-line-hover-18);
  --usage-text: var(--color-usage-usage-text-19);
  --usage-muted: var(--color-usage-usage-muted-20);
  --usage-accent: var(--color-usage-usage-accent-21);
  --usage-inset: var(--color-usage-usage-inset-22);
  --usage-green: var(--color-usage-usage-green-23);
  --usage-yellow: var(--color-usage-usage-yellow-24);
  --usage-queued-color: var(--color-usage-usage-yellow-24);
}
.usage :is(a, button, summary):focus-visible {
  outline: 2px solid var(--appearance-focus, var(--billing-focus-ink));
  outline-offset: 3px;
}
.usage a {
  color: var(--usage-accent);
}
.usage a:hover:not(:global(.button-interaction)) {
  text-decoration: underline;
}

.arc {
  transition:
    stroke-dashoffset 0.3s ease,
    stroke 0.3s ease;
}
@media (prefers-reduced-motion: reduce) {
  .arc {
    transition: none;
  }
}

@font-face {
  font-family: "Usage Inter";
  src: url("/fonts/inter/InterVariable.woff2") format("woff2");
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
}

/* Keep Purple's Premium icon and all existing sizing intact. */

/* Usage owns these tokens, including copies on its portaled surfaces.
   The light palette below overrides the default dark palette. */
:global(html[data-workspace][data-appearance="vercel"]) :is(.usage, .surface) {
  --usage-bg: var(--color-usage-usage-bg-28);
  --usage-card: var(--color-usage-usage-card-29);
  --usage-inset: var(--color-usage-usage-inset-30);
  --usage-line: var(--color-usage-usage-line-31);
  --usage-control-line: var(--color-usage-usage-control-line-32);
  --usage-button-line: var(--color-usage-usage-button-line-33);
  --usage-raised: var(--color-usage-usage-raised-34);
  --usage-track: var(--color-usage-usage-track-35);
  --usage-line-hover: var(--color-usage-usage-button-line-33);
  --usage-text: var(--color-usage-usage-text-36);
  --usage-number: var(--color-usage-usage-button-ink-8);
  --usage-muted: var(--color-usage-usage-muted-37);
  --usage-accent: var(--color-usage-usage-text-36);
  --usage-green: var(--color-usage-usage-green-38);
  --usage-yellow: var(--color-usage-usage-yellow-39);
  --usage-warning-line: var(--color-usage-usage-warning-line-40);
  --usage-queued-color: var(--usage-yellow);
  --usage-error: var(--color-usage-usage-error-41);
  --usage-error-line: var(--color-usage-usage-error-line-42);
  --usage-error-bg: var(--color-usage-usage-error-bg-43);
  --usage-coral: var(--color-usage-usage-coral-44);
  --usage-primary: var(--color-usage-usage-primary-45);
  --usage-button-ink: var(--color-usage-usage-bg-28);
  --usage-gradient: var(--usage-primary);
  --usage-plan-gradient: var(--usage-line);
  --usage-glow: none;
  --usage-ring-start: var(--usage-green);
  --usage-ring-end: var(--usage-green);
  --usage-ring-paint: var(--usage-green);
  --usage-warning-bg: var(--color-usage-usage-warning-bg-46);
  --usage-disabled-bg: var(--color-usage-usage-line-31);
  --usage-font: "Usage Inter", Arial, Helvetica, sans-serif;
  --usage-card-radius: 12px;
  --usage-button-radius: 8px;
  --usage-input-radius: 8px;
  --usage-chip-radius: 6px;
  --usage-badge-radius: 6px;
  --usage-tile-radius: 12px;
  --usage-bar-radius: 6px;
  --appearance-radius: var(--usage-card-radius);
  --appearance-control-radius: var(--usage-button-radius);
  --appearance-badge-radius: var(--usage-chip-radius);
  /* Existing utility classes inherit the same local palette. */
  --background: var(--usage-bg);
  --card: var(--usage-card);
  --surface: var(--usage-inset);
  --foreground: var(--usage-text);
  --body: var(--usage-muted);
  --muted-foreground: var(--usage-muted);
  --separator: color-mix(in srgb, var(--muted-foreground) 85%, transparent);
  --border: var(--usage-line);
  --border-hover: var(--usage-line-hover);
  --control-border: var(--usage-control-line);
  --link: var(--usage-accent);
  --ring: var(--usage-number);
  --accent: var(--usage-text);
  --appearance-focus: var(--usage-number);
  --appearance-link: var(--usage-accent);
  --appearance-wash: var(--usage-inset);
  --appearance-border: var(--usage-line-hover);
  --appearance-card: var(--usage-card);
  --appearance-decoration: none;
  --appearance-shadow: none;
  --appearance-focus-shadow: none;
  --plan-pink: var(--usage-text);
  --font-plus-jakarta: var(--usage-font);
  --tooltip-green: var(--usage-green);
  --tooltip-yellow: var(--usage-yellow);
  --tooltip-pink: var(--usage-text);
  background: var(--usage-bg);
  color: var(--usage-text);
  font-family: var(--usage-font);
}
:global(html[data-workspace][data-appearance="vercel"][data-theme="light"])
  :is(.usage, .surface) {
  --usage-bg: var(--color-workspace-theme-background-4);
  --usage-card: var(--color-workspace-theme-card-6);
  --usage-inset: var(--color-workspace-theme-surface-5);
  --usage-disabled-bg: var(--usage-inset);
  --usage-line: var(--color-workspace-theme-border-8);
  --usage-control-line: var(--color-workspace-theme-control-border-10);
  --usage-button-line: var(--color-workspace-theme-control-border-10);
  --usage-raised: var(--color-workspace-theme-highlight-background-1);
  --usage-track: var(--color-workspace-theme-border-8);
  --usage-line-hover: var(--color-workspace-theme-border-hover-9);
  --usage-text: var(--color-workspace-theme-highlight-foreground-2);
  --usage-number: var(--usage-text);
  --usage-muted: var(--color-workspace-theme-muted-foreground-7);
  --usage-accent: var(--usage-text);
  --usage-green: var(--usage-text);
  --usage-yellow: var(--color-workspace-theme-status-warning-text-14);
  --usage-queued-color: var(--color-workspace-theme-queued-12);
  --usage-warning-line: var(--color-workspace-theme-recipients-pill-border-20);
  --usage-warning-bg: var(--color-workspace-theme-warning-soft-16);
  --usage-error: var(--color-workspace-theme-status-error-text-15);
  --usage-error-line: color-mix(
    in srgb,
    var(--usage-error) 30%,
    var(--usage-card)
  );
  --usage-error-bg: color-mix(
    in srgb,
    var(--usage-error) 8%,
    var(--usage-card)
  );
  --usage-coral: var(--color-workspace-theme-coral-17);
  --usage-primary: var(--usage-text);
  --usage-button-ink: var(--usage-card);
}
:global(html[data-workspace][data-appearance="vercel"])
  .usage
  :global(.hover-card):hover {
  transform: none;
  border-color: var(--usage-line-hover);
  box-shadow: none;
}
:global(html[data-workspace][data-appearance="vercel"]) :is(.tag, .resetPill) {
  border-radius: var(--usage-badge-radius);
  background: var(--usage-warning-bg);
  border-color: var(--usage-warning-line);
}
:global(html[data-workspace][data-appearance="vercel"])
  .usage
  :global(.plan-mode-badge) {
  background: var(--usage-warning-bg);
  border-color: var(--usage-warning-line);
}
:global(html[data-workspace][data-appearance="vercel"]) .surface {
  background: var(--usage-card);
  border-color: var(--usage-line);
  border-radius: var(--usage-card-radius);
  box-shadow: none;
}
:global(html[data-workspace][data-appearance="vercel"]) .surface a {
  color: var(--usage-accent);
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.usage, .surface)
  :is(a, button, summary):focus-visible {
  outline: 2px solid var(--usage-number);
  outline-offset: 3px;
  border-color: var(--usage-number);
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.usage, .surface)
  :is(input, select, textarea) {
  background: var(--usage-inset);
  color: var(--usage-text);
  border-color: var(--usage-control-line);
  border-radius: var(--usage-input-radius);
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.usage, .surface)
  :is(button, input, select, textarea):disabled {
  opacity: 1;
  background: var(--usage-disabled-bg);
  color: var(--usage-muted);
  border-color: var(--usage-line-hover);
  box-shadow: none;
}

:global(html[data-workspace][data-appearance="vercel"])
  .usage
  :is(.heading > p, .label, .planCard :global(.font-mono)) {
  font-family: var(--font-jetbrains), monospace;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}
:global(html[data-workspace][data-appearance="vercel"])
  .usage
  :is(input, select, textarea) {
  border-radius: var(--usage-input-radius);
}
:global(html[data-workspace][data-appearance="vercel"])
  .surface
  [role="menuitem"] {
  border-radius: var(--usage-button-radius);
}
:global(html[data-workspace][data-appearance="vercel"])
  .usage
  :global(.plan-mode-badge) {
  border-radius: var(--usage-badge-radius);
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.usage, .surface)
  :is(button, [role="button"], :global(.button-interaction)) {
  --button-hover-filter: none;
}
